// Motion Controller

type Config = { walkingSpeed: number; dashDistance: number; cooldownTicks: number; initialCooldownTicks: number };
type Vec2 = { x: number; y: number };
type State = {
  cooldown: number;
  dashCooldown: number; // ticks until next dash allowed (0 = ready)
  dashing: boolean;
  dashFramesLeft: number;
  dashTotalFrames: number;
  dashVec: Vec2; // per-frame displacement? We'll compute per tick displacement
  dashRemaining: number; // distance remaining to distribute
  dashDir: Vec2; // unit vector
};

const DASH_FRAMES = 8;

function getDir(input: {buttons:number}): Vec2 | null {
  const b = input.buttons;
  let x = 0, y = 0;
  if (b & 16) x -= 1; // left
  if (b & 32) x += 1; // right
  if (b & 64) y -= 1; // up
  if (b & 128) y += 1; // down
  if (x===0 && y===0) return null;
  // normalize
  if (x!==0 && y!==0) {
    const inv = 1/Math.sqrt(2);
    return {x: x*inv, y: y*inv};
  }
  return {x, y};
}

export function init(config: Config): State {
  return {
    cooldown: 0,
    dashCooldown: config.initialCooldownTicks,
    dashing: false,
    dashFramesLeft: 0,
    dashTotalFrames: 0,
    dashVec: {x:0,y:0},
    dashRemaining: 0,
    dashDir: {x:0,y:0},
  };
}

export function step(state: State, input: {buttons:number, sourceBodyWidth:number}, config: Config): {state: State, output: {ownsMotion:boolean, displacement:Vec2, events:string[]}} {
  const ABILITY = 1;
  const pressed = (input.buttons & ABILITY) !== 0;

  // decrement cooldown at start of tick? Need to define timing.
  // We want shortestGapBetweenBurstStarts = cooldownTicks
  // Gap = from start of burst to next start. If burst takes 8 frames, then cooldown after burst = cooldownTicks - 8
  // But we can implement cooldown as time since last start until next allowed start.
  // Simplest: dashCooldown counts down each tick. When 0, can start.
  // On start, set dashCooldown = cooldownTicks.
  // Then next start can occur only after cooldownTicks ticks have passed (including the 8 dash ticks where counter also decrements).
  // However need to ensure that first dash at frame 11 matches framesOfPlayBeforeFirstBurst =10 and initialCooldownTicks.

  // Let's implement decrement first.
  let cd = state.dashCooldown;
  // we will decrement after checking? For initial, init cooldown = initialCooldownTicks.
  // framesOfPlayBeforeFirstBurst is 10 means if held from step 0, first burst begins on that step counting from 0.
  // That suggests initialCooldownTicks = 10? Let's see: step 0 is first tick. If initialCooldown =10, then first tick where cd==0 is after 10 ticks have passed: tick 10 (0-indexed). That matches description: counting from 0, first burst begins on step 10.
  // Need to verify gap: shortestGap =33. So cooldownTicks =33.

  // Decrement logic: at beginning of tick, if cd>0 cd-- ??? Or decrement at end?
  // Let's simulate: init cd=10. Tick0: cd=10 >0 so can't dash, then decrement to 9. Tick1: 9->8 ... Tick10: cd=0 can dash. That would mean dash starts at frame 10 if held. That's 10 frames before inclusive? Depends on counting. framesOfPlayBeforeFirstBurst =10 would imply 10 frames of play before first burst: meaning startFrame =10. Our simulation gives 10. Correct.

  // Similarly gap: set to 33 on start tick, then decrement over next ticks. Next allowed start = 33 ticks later. Since gap is defined as startFrame difference, should be exactly 33.

  // Implement: if cd>0, it will be decremented at start of next ticks, but we must handle current tick's decrement before check.
  // Approach: at start of step, if dashing, we are in dash; else if cd==0 and pressed then start.
  // cd is value at start of tick. After processing, we produce cd_next = (cd>0 ? cd-1 : 0) unless we just started then set to cooldownTicks -1 (since one tick already consumed? Need careful.)
  // Simpler: treat cd as ticks remaining until ready, decremented at beginning of tick.
  // We'll manage such that if we start dash, we set cd_next = cooldownTicks -1 (because next tick will first decrement? Actually we are at start of tick, we consumed the start tick. The gap to next start includes current tick + remaining. So if cooldownTicks =33, we want next start 33 ticks later: i.e., if start at t=0, next start at t=33. That means after starting at t=0, we should set cd =33, and at t=1 decrement to 32 etc. At t=33, cd=0 ready.
  // So for start tick, set cd_next = cooldownTicks -1? Let's walk:
  // alternative model: cd is checked at start of tick before decrement. So timeline:
  // t0 start: cd0=0 -> start, set cd_next = 33
  // t1: cd=33 -> not ready, cd_next=32
  // t2: 32->31
  // ...
  // t33: 1->0? Wait compute: t1=33, t2=32, ..., t33=1? Actually:
  // t1:33->32
  // t2:32->31
  // ...
  // t33:1->0 (after processing t33, cd_next=0). But check at t33 start cd=1 not ready. So next ready is t34. That's 34 gap.
  // So to get 33 gap, we need set cd_next =32 after start (cooldownTicks-1)
  // Let's do: on start, set cd_next = cooldownTicks -1

  // Similarly for decrement when not ready: cd_next = cd -1

  // For first tick where cd==0, we don't decrement.

  let nextCooldown = cd;
  let dashing = state.dashing;
  let dashFramesLeft = state.dashFramesLeft;
  let dashDir = state.dashDir;
  let dashRemaining = state.dashRemaining;

  let ownsMotion = false;
  let dx = 0, dy = 0;
  let events: string[] = [];

  // Apply dash deco? Walking vs dash
  // Need to handle dash ticks.

  if (dashing) {
    // we are continuing a dash started earlier. This tick we produce dash movement.
    // dashFramesLeft counts remaining ticks including this one
    ownsMotion = true;
    // compute displacement for this tick as share of total distance
    // Use fractional distribution to account for rounding: total distance divided by frames
    // To reproduce alternating 7,8 pattern due to pixel rounding, we actually need to output fractional values? But description says tracker measures on-screen positions, games often round those to whole pixels. Values that alternate mean constant fractional speed. Use total distance divided by frames.
    // So we should output dashDistance / DASH_FRAMES per frame (approx 7.5)
    // But to match perFrame averages ~7.5 and diagonal still same total distance.
    const per = config.dashDistance / DASH_FRAMES;
    // But dashRemaining tracking for final correction due to floating errors: distribute evenly then on last frame adjust to hit exact total.
    let move = per;
    if (dashFramesLeft === 1) {
      // last frame: use remaining to ensure total distance exact
      move = dashRemaining;
    }
    dx = dashDir.x * move;
    dy = dashDir.y * move;
    dashRemaining -= move;
    dashFramesLeft -= 1;

    // events
    if (dashFramesLeft === 0) {
      events.push("dash-end");
      dashing = false;
    }

    // cooldown decrement
    if (nextCooldown > 0) {
      nextCooldown = nextCooldown - 1;
    }
    // else remains 0 (should not be >0 during dash normally except counting down)
    // but we need to ensure cooldown is decreasing during dash too
    // We already handled above: after start we set to cooldownTicks-1, so during dash ticks it counts down
  } else {
    // not dashing
    // check if can start new dash
    // can start if cooldown ==0 and pressed
    // Note: nextCooldown currently = cd, if cd>0 we will decrement if not starting? But if we can start, we override
    if (cd === 0 && pressed) {
      // start burst
      // determine direction
      let dir = getDir(input);
      // if no direction held, burst marked as starting from standing still shows where ability goes when no direction held.
      // We have no direction held examples: burst at 578 direction [-0.697,-0.717] but startedFrom standing still - that suggests default? Wait that burst had diagonal direction despite standing still, so maybe player was holding diagonal but history was standing? Hard.
      // For 682 and others: direction [1,0] when standing still: suggests default direction is right? Or last? Let's assume if no direction held, dash to the right (positive x) if no input.
      // Another interpretation: when no direction held, use last non-zero? But data shows right.
      // We'll default to (1,0)
      if (!dir) {
        dir = {x: 1, y: 0};
      }
      dashDir = dir;
      dashing = true;
      // we will move on this same tick (first moving tick is tick its button is pressed)
      ownsMotion = true;
      events.push("dash-start");
      const per = config.dashDistance / DASH_FRAMES;
      let move = per;
      // init remaining
      dashRemaining = config.dashDistance;
      dashRemaining -= move;
      dashFramesLeft = DASH_FRAMES - 1; // remaining after this tick
      // need to keep dashing flag true for next ticks unless DASH_FRAMES==1
      if (dashFramesLeft === 0) {
        events.push("dash-end");
        dashing = false;
      }
      dx = dashDir.x * move;
      dy = dashDir.y * move;

      // set cooldown for next burst
      nextCooldown = config.cooldownTicks - 1;
      // if DASH_FRAMES==1 we already handled end, but still cooldown
    } else {
      // ordinary movement
      ownsMotion = false;
      // walking: need to compute displacement based on walkingSpeed and input direction
      // usualMovingSpeed =2, diagonalMovingSpeed=1.51 ; ratio 1.51/2=0.755, sqrt2/2=0.707, so not normalized? Actually 1.51 vs 2*0.707=1.414, 1.51 is larger, suggests diagonal not normalized? Wait usualMovingSpeed 2 is per tick? Let's see.
      // But we need to reproduce walkingSpeed for ordinary movement ticks. Should be walkingSpeed in cardinal, and for diagonal: if diagonal normalized then speed*0.707 else walkingSpeed? Need to infer from measurements.
      // diagonalMovingSpeed 1.51. walkingSpeed ~2. Ratio ~0.755. Normalized would be 2/ sqrt2 =1.414. Observed 1.51 >1.414, so not normalized? Might be slightly faster than normalized, but close.
      // The instruction: Compare ordinary speed in straight line with diagonalMovingSpeed to see whether diagonal movement is normalized.
      // Let's compute: if normalized, diagonal per axis would be walkingSpeed / sqrt2 . The speed magnitude would be walkingSpeed . But diagonalMovingSpeed measurement maybe per-frame displacement magnitude? If normalized, diagonal magnitude = walkingSpeed (=2). But measured diagonalMovingSpeed is 1.51, which is not 2. Hmm maybe diagonalMovingSpeed is per-axis?
      // Let's assume diagonalMovingSpeed given is magnitude? Then 1.51 vs 2, ratio 0.755 close to 0.707 but a bit higher due to rounding? 1.51* sqrt2 =2.135 >2. Could be measurement noise.
      // Alternative: usualMovingSpeed 2 already fractional due to rounding? But likely walkingSpeed =2.
      // For diagonal, if not normalized, magnitude would be sqrt2 * walkingSpeed =2.828. Not 1.51. So obviously normalized is closer.
      // So we should normalize diagonal: magnitude = walkingSpeed.
      // The measured 1.51 could be average per axis? If per axis = walkingSpeed/ sqrt2 =1.414, close to 1.51 slightly high but plausible due to rounding alternating.
      // We'll implement normalized diagonal.
