export function step(state: any, input: any, config: any): any {
  const ABILITY = 1;
  const LEFT = 16;
  const RIGHT = 32;
  const UP = 64;
  const DOWN = 128;

  let ownsMotion = false;
  let dx = 0;
  let dy = 0;
  let events: string[] = [];

  const leftHeld = (input.buttons & LEFT) !== 0;
  const rightHeld = (input.buttons & RIGHT) !== 0;
  const upHeld = (input.buttons & UP) !== 0;
  const downHeld = (input.buttons & DOWN) !== 0;
  const abilityHeld = (input.buttons & ABILITY) !== 0;

  const dashDuration = 8;
  const perFrameDist = config.dashDistance / dashDuration;

  // If currently dashing, continue
  if (state.dashing) {
    ownsMotion = true;
    dx = perFrameDist * state.dashDirX;
    dy = perFrameDist * state.dashDirY;
    state.dashFramesLeft -= 1;
    if (state.dashFramesLeft <= 0) {
      state.dashing = false;
      events.push("dash-end");
      state.cooldown = config.cooldownTicks;
    }
    return { state, output: { ownsMotion, displacement: { x: dx, y: dy }, events } };
  }

  // Not dashing: check if ability can start BEFORE decrementing cooldown
  // Cooldown is number of ticks that must elapse between dash start ticks minus dashDuration
  // shortestGap = dashDuration + cooldownTicks => 33 => 8+25=33
  // We want holding ability to repeat every 33 ticks.
  // Timing: start at T, dash T..T+7, cooldown enforced for ticks T+8 .. T+32 inclusive? Let's define.
  // Simplest: after dash ends, set cooldown = cooldownTicks, and each non-dashing tick decrement.
  // But dash start should only be allowed when cooldown == 0.
  // With cooldownTicks=25, start T, end at T+7, cooldown=25.
  // Next ticks: T+8: cd 25 -> decrement to 24? We need careful.
  // If we decrement only when not starting dash, gap becomes cooldownTicks + dashDuration =33.

  if (abilityHeld && state.cooldown <= 0) {
    let ix = 0;
    let iy = 0;
    if (leftHeld) ix -= 1;
    if (rightHeld) ix += 1;
    if (upHeld) iy -= 1;
    if (downHeld) iy += 1;

    let dirX = 0;
    let dirY = 0;
    if (ix === 0 && iy === 0) {
      dirX = state.lastDirX;
      dirY = state.lastDirY;
    } else {
      const len = Math.sqrt(ix * ix + iy * iy);
      dirX = ix / len;
      dirY = iy / len;
      state.lastDirX = dirX;
      state.lastDirY = dirY;
    }

    state.dashing = true;
    state.dashFramesLeft = dashDuration;
    state.dashDirX = dirX;
    state.dashDirY = dirY;

    ownsMotion = true;
    dx = perFrameDist * dirX;
    dy = perFrameDist * dirY;
    events.push("dash-start");
    state.dashFramesLeft -= 1;
    if (state.dashFramesLeft <= 0) {
      state.dashing = false;
      events.push("dash-end");
      state.cooldown = config.cooldownTicks;
    }
    return { state, output: { ownsMotion, displacement: { x: dx, y: dy }, events } };
  }

  // Not dashing and not starting: decrement cooldown
  if (state.cooldown > 0) {
    state.cooldown -= 1;
  }

  // Ordinary movement
  {
    let ix = 0;
    let iy = 0;
    if (leftHeld) ix -= 1;
    if (rightHeld) ix += 1;
    if (upHeld) iy -= 1;
    if (downHeld) iy += 1;
    if (ix !== 0 || iy !== 0) {
      const len = Math.sqrt(ix * ix + iy * iy);
      state.lastDirX = ix / len;
      state.lastDirY = iy / len;
      dx = config.walkingSpeed * (ix / len);
      dy = config.walkingSpeed * (iy / len);
    } else {
      dx = 0;
      dy = 0;
    }
  }

  ownsMotion = false;
  return { state, output: { ownsMotion, displacement: { x: dx, y: dy }, events } };
}

